import fs from "node:fs";
import path from "node:path";
import { execFileSync } from "node:child_process";
import type { Editor } from "@tiptap/core";
import type { Browser, Locator, Page } from "@playwright/test";
import { test, expect } from "../../fixtures/test-base";
import { SessionPage } from "../../pages/session-page";
import { prepareDenseComparisonFixture } from "../../helpers/dense-comparison-fixture";
import { verifyDenseThreadsFiles } from "../../helpers/dense-threads-fixture";
import { hashAssetTree, sha256File } from "../../helpers/dense-snapshot";
import {
  createDenseAttempts,
  recordDenseAttempt,
  runDenseAttempts,
} from "../../helpers/dense-attempts";
import { copyDenseBackendLog } from "../../helpers/dense-evidence";

test.skip(
  process.env.KANDEV_PLAN_EXTENSION_COMPARE !== "1",
  "private opt-in plan engine comparison",
);

function planDocument(steps: number) {
  return [
    "# Deterministic plan",
    ...Array.from({ length: steps }, (_, index) =>
      [
        `## Step ${index + 1}`,
        `- [ ] Verify [reference ${index + 1}](https://example.com/step-${index + 1}) with **bold**, *italic* and <u>underlined text</u>.`,
        `Keep the task result and the next action clear. Plan marker ${index + 1}.`,
      ].join("\n\n"),
    ),
  ].join("\n\n");
}

async function settle(page: Page) {
  await page.evaluate(
    () =>
      new Promise<void>((resolve) => {
        requestAnimationFrame(() => requestAnimationFrame(() => resolve()));
      }),
  );
}

async function measurePlan(editorElement: Locator, content: string) {
  return editorElement.evaluate(async (element, markdown) => {
    const editor = (element as HTMLElement & { editor: Editor }).editor;
    if (!editor || editor.isDestroyed) throw new Error("Plan editor is unavailable");
    const frame = () =>
      new Promise<void>((resolve) => {
        requestAnimationFrame(() => requestAnimationFrame(() => resolve()));
      });
    const assert = (ok: boolean, message: string) => {
      if (!ok) throw new Error(message);
    };
    editor.commands.setContent(markdown, { emitUpdate: false });
    const documentJson = JSON.stringify(editor.getJSON());
    const baseText = editor.state.doc.textContent;
    const replace = [] as Array<{ durationMs: number; readyMs: number }>;
    const insert = [] as Array<{ durationMs: number; readyMs: number }>;
    for (let index = 0; index < 3; index++) {
      editor.commands.setContent(markdown, { emitUpdate: false });
      await frame();
    }
    for (let index = 0; index < 24; index++) {
      const start = performance.now();
      editor.commands.setContent(markdown, { emitUpdate: false });
      const end = performance.now();
      await frame();
      replace.push({ durationMs: end - start, readyMs: performance.now() - start });
      assert(JSON.stringify(editor.getJSON()) === documentJson, "Plan replacement changed content");
    }
    editor.commands.focus("end");
    for (let index = 0; index < 3; index++) {
      editor.view.dispatch(editor.state.tr.insertText("x"));
      await frame();
    }
    editor.commands.setContent(markdown, { emitUpdate: false });
    editor.commands.setTextSelection(editor.state.doc.content.size - 1);
    await frame();
    for (let index = 0; index < 24; index++) {
      const start = performance.now();
      editor.view.dispatch(editor.state.tr.insertText("x"));
      const end = performance.now();
      await frame();
      insert.push({ durationMs: end - start, readyMs: performance.now() - start });
      assert(
        editor.state.doc.textContent === baseText + "x".repeat(index + 1),
        "Plan edit lost text",
      );
    }
    const links = Array.from(editor.view.dom.querySelectorAll("a")).map((anchor) =>
      anchor.getAttribute("href"),
    );
    assert(links.length > 0 && links[0] === "https://example.com/step-1", "Plan lost links");
    assert(
      editor.view.dom.querySelector("u")?.textContent === "underlined text",
      "Plan lost underline",
    );
    return {
      inputBytes: new TextEncoder().encode(markdown).length,
      baseTextCharacters: baseText.length,
      topLevelNodes: editor.state.doc.childCount,
      replace,
      insert,
      verifiedReplacements: replace.length,
      verifiedInserts: insert.length,
      links: links.length,
      pluginCount: editor.state.plugins.length,
      linkPluginKeys: editor.state.plugins
        .map((plugin) => (plugin as unknown as { key: string }).key)
        .filter((key) => /autolink|handleClickLink|handlePasteLink/.test(key)),
      markNames: editor.extensionManager.extensions
        .map((extension) => extension.name)
        .filter((name) => name === "link" || name === "underline"),
    };
  }, content);
}

async function openTaskPlan(page: Page, taskId: string) {
  const startedAt = performance.now();
  await page.goto(`/t/${taskId}`);
  const session = new SessionPage(page);
  await session.waitForLoad();
  if (!(await session.planPanel.isVisible())) await session.togglePlanMode();
  await expect(session.planEditor()).toBeVisible({ timeout: 30_000 });
  await expect
    .poll(() =>
      session
        .planEditor()
        .evaluate((element) => Boolean((element as HTMLElement & { editor?: Editor }).editor)),
    )
    .toBe(true);
  await settle(page);
  return { session, readyMs: performance.now() - startedAt };
}

async function createPlanPage(browser: Browser, frontendUrl: string, port: number) {
  const context = await browser.newContext({
    baseURL: frontendUrl,
    viewport: { width: 1470, height: 956 },
    deviceScaleFactor: 2,
    locale: "en-US",
    reducedMotion: "no-preference",
  });
  const page = await context.newPage();
  await page.addInitScript((apiPort) => {
    localStorage.setItem("kandev.onboarding.completed", "true");
    window.__KANDEV_API_PORT = apiPort;
    window.__KANDEV_E2E_EXPOSE_STORE__ = true;
  }, String(port));
  return { page, context };
}

test("compares real plan editor transactions on the frozen dense task fixture", async ({
  browser,
  testPage,
  apiClient: api,
  seedData: seed,
  backend,
}, info) => {
  test.setTimeout(1_800_000);
  const baseline = process.env.KANDEV_DENSE_BASELINE_ROOT;
  if (!baseline) throw new Error("Frozen baseline is required");
  const candidate = path.resolve(process.cwd(), "../..");
  const builds = Object.fromEntries(
    Object.entries({ baseline, candidate }).map(([arm, root]) => {
      const binary = path.join(root, "apps/backend/bin/kandev");
      const assets = path.join(root, "apps/web/dist");
      return [
        arm,
        { binary, assets, binarySha256: sha256File(binary), assetsSha256: hashAssetTree(assets) },
      ];
    }),
  );
  const prepared = await prepareDenseComparisonFixture(api, seed, backend, testPage);
  const directory = path.join(candidate, ".kandev/diagnostics/dense-workbench-performance");
  fs.mkdirSync(directory, { recursive: true });
  const output = path.join(directory, `plan-extension-comparison-${Date.now()}.json`);
  const browserCdp = await browser.newBrowserCDPSession();
  const browserEnvironment = {
    version: await browserCdp.send("Browser.getVersion"),
    system: await browserCdp.send("SystemInfo.getInfo"),
  };
  await browserCdp.detach();
  const report = {
    browserEnvironment,
    measurementKind: "real-plan-engine-transactions",
    protocol: "plan-extension-paired-v1",
    sourceRevision: execFileSync("git", ["rev-parse", "HEAD"], {
      cwd: candidate,
      encoding: "utf8",
    }).trim(),
    sourcePatch: execFileSync("git", ["diff", "--binary", "HEAD"], {
      cwd: candidate,
      encoding: "utf8",
    }),
    sourceText: fs.readFileSync(
      path.join(candidate, "apps/web/e2e/tests/performance/plan-extension-comparison.spec.ts"),
      "utf8",
    ),
    builds,
    fixture: prepared.fixture,
    fixtureReplay: prepared.provenance,
    databaseSha256: sha256File(prepared.snapshot),
    comparisonPlan: { pairs: 6, rates: [1], candidateFirst: false },
    attempts: createDenseAttempts({ pairs: 6, rates: [1], candidateFirst: false }),
    samples: [] as unknown[],
    checkpoints: {} as Record<string, Record<string, unknown>>,
    error: undefined as string | undefined,
    scope:
      "Synchronous real-editor Markdown replacements and ProseMirror insertText dispatches, with two animation frames between operations. Readiness is an upper bound, not INP or presentation. No stream or startup speed claim.",
  };
  const save = () => fs.writeFileSync(output, JSON.stringify(report, null, 2));
  save();
  try {
    await runDenseAttempts(
      report.attempts,
      async ({ arm, pair, cpuRate, sample }) => {
        const database = path.join(backend.tmpDir, `${prepared.sampleNamespace}plan-${sample}.db`);
        fs.copyFileSync(prepared.snapshot, database);
        expect(sha256File(database)).toBe(report.databaseSha256);
        await backend.restart(
          {
            KANDEV_DATABASE_PATH: database,
            KANDEV_HOME_DIR: path.join(
              backend.tmpDir,
              `${prepared.sampleNamespace}plan-${sample}-home`,
            ),
            KANDEV_WEB_DIST_DIR: builds[arm].assets,
            KANDEV_LOG_LEVEL: "warn",
            ...prepared.restartEnv,
          },
          builds[arm].binary,
        );
        expect((await api.listTasks(prepared.seed.workspaceId)).total).toBe(1000);
        const filesBefore = await verifyDenseThreadsFiles(api, prepared.backend, prepared.fixture);
        await api.wsRequest("task.plan.create", {
          task_id: prepared.fixture.threads[0].taskId,
          title: "Dense plan comparison",
          content: planDocument(20),
          created_by: "user",
        });
        const { page, context } = await createPlanPage(browser, backend.frontendUrl, backend.port);
        const warnings: string[] = [];
        const pageErrors: string[] = [];
        page.on("console", (message) => {
          if (/Duplicate extension names/.test(message.text())) warnings.push(message.text());
        });
        page.on("pageerror", (error) => pageErrors.push(String(error)));
        const cdp = await context.newCDPSession(page);
        await cdp.send("Emulation.setCPUThrottlingRate", { rate: 1 });
        const scenarios: Record<string, unknown> = {};
        report.checkpoints[sample] = { filesBefore, scenarios };
        save();
        try {
          const { session, readyMs } = await openTaskPlan(page, prepared.fixture.threads[0].taskId);
          for (const steps of [20, 400]) {
            scenarios[String(steps)] = await measurePlan(session.planEditor(), planDocument(steps));
            save();
          }
          const editor = session.planEditor();
          await editor.focus();
          const beforeNative = await editor.evaluate(
            (element) => (element as HTMLElement & { editor: Editor }).editor.state.doc.textContent,
          );
          await page.keyboard.insertText(" native-input-control");
          await expect
            .poll(() =>
              editor.evaluate(
                (element) =>
                  (element as HTMLElement & { editor: Editor }).editor.state.doc.textContent,
              ),
            )
            .toBe(beforeNative + " native-input-control");
          expect(pageErrors).toEqual([]);
          if (arm === "baseline") expect(warnings.length).toBeGreaterThan(0);
          else expect(warnings).toEqual([]);
          const filesAfter = await verifyDenseThreadsFiles(api, prepared.backend, prepared.fixture);
          expect(filesAfter).toEqual(filesBefore);
          return {
            arm,
            pair,
            cpuRate,
            sample,
            scenarios,
            readyMs,
            warnings,
            pageErrors,
            filesBefore,
            filesAfter,
            nativeInputVerified: true,
          };
        } finally {
          await cdp.detach();
          await context.close();
        }
      },
      (outcome) => {
        recordDenseAttempt(report, outcome);
        const backendLog = copyDenseBackendLog(
          path.join(backend.tmpDir, "backend-process.log"),
          `${output}.${outcome.sample}.backend.log`,
        );
        report.checkpoints[outcome.sample] = { ...report.checkpoints[outcome.sample], backendLog };
        save();
      },
    );
  } catch (error) {
    report.error = String(error);
    save();
    throw error;
  } finally {
    await info.attach("plan-extension-comparison", {
      path: output,
      contentType: "application/json",
    });
  }
});
